Definition lspill (M : word -> option byte) (E F op ov oec : Z) : Prop :=
  L5.u64_at RSEGS M (E - 264) (F + 32) /\ L5.u64_at RSEGS M (E - 256) 3 /\ L5.u64_at RSEGS M (E - 248) 1 /\ L5.u64_at RSEGS M (E - 240) 0
