  /\ L5.u64_at RSEGS M (E - 192) (op + 360) /\ L5.u64_at RSEGS M (E - 184) F /\ L5.u64_at RSEGS M (E - 176) 65024 /\ L5.u64_at RSEGS M (E - 168) (op + 24)
  /\ L5.u64_at RSEGS M (E - 160) (oec / 8 + 2147450880) /\ L5.u64_at RSEGS M (E - 152) op /\ L5.u64_at RSEGS M (E - 144) ov
